import { getMetaContent } from "helpers/meta_helpers"

let translations = {}
let translationsSource = null

export function currentLocale() {
  return getMetaContent("locale") || document.documentElement.lang || "en"
}

// Looks up a translation from the `js` scope of the current locale, as rendered
// into the page by `javascript_i18n_meta_tags`. Interpolates `%{name}` placeholders.
export function t(key, interpolations = {}) {
  const translation = key.split(".").reduce((scope, part) => scope?.[part], loadTranslations())
  if (translation === undefined) return key

  return Object.entries(interpolations).reduce(
    (result, [ name, value ]) => result.replaceAll(`%{${name}}`, value),
    translation
  )
}

function loadTranslations() {
  const source = getMetaContent("i18n-translations")
  if (source !== translationsSource) {
    translationsSource = source
    translations = source ? JSON.parse(source) : {}
  }
  return translations
}
