  attrs = text.scan(/(?:title|placeholder|aria-label|alt|aria-description|data-text|label)="([^"]*)"/).flatten
  no_tags = text.gsub(/<[^>]*>/m, " ")
  words = no_tags.scan(/[A-Za-z][A-Za-z'’]+(?:\s+[A-Za-z'’]+)*/).select { |w| w =~ /[a-z]/ && w.length > 2 }
  words = words.reject { |w| w =~ /\A(nbsp|amp|gt|lt|middot|Fizzy|HEY|Basecamp|DEV|ESC|Turbo|Fizzy|https?|www|jason|signals|com|support|do|fizzy|kbd|svg|path|div|span|li|ul|ol|h\d|em|strong|code|kbd|end|do|if|else)\z/i }
  ruby = stripped.scan(/<%(.*?)%>/m).flatten.join("\n")
  ruby_strings = ruby.scan(/"([^"\\]*(?:\\.[^"\\]*)*)"/).flatten.select { |s| s =~ /\b[A-Z][a-z]+\b.*[a-z]|\b[a-z]+ [a-z]+\b/ && s !~ /^[\w\-\.:#\/\[\]\(\)>@,;&\s\*\+\|=\?!%\$\{\}\\']*$/ }
  ruby_strings = ruby_strings.reject { |s| s =~ /\A[\w\-]+(\s[\w\-]+)*\z/ && s !~ /[A-Z]/ && s.split.size == 1 }
  ruby_strings = ruby_strings.reject { |s| s =~ /^(keydown|click|input|turbo|change|submit|focus|blur|dialog|mouseenter|lexxy|toggle|open-export|drag|drop|compositionstart|paste|animationend|search-form|filter:|bridge|passkey|form#|one-time-code|username|off|email|name|search|button|checkbox|radio|hidden|text|submit|dialog|delete|patch|post|get|put)/ }
  ruby_strings = ruby_strings.reject { |s| s =~ /^[\w\-]+( [\w\-]+)*$/ && s.split.all? { |w| w =~ /^[a-z\-]+(#|->|@)/ } }
  ruby_strings = ruby_strings.select { |s| s =~ /[A-Z][a-z]|[a-z] [a-z]/ }.reject { |s| s =~ /^(var\(|--|#{Regexp.escape('%')}|[A-Z][a-z]+::|\S+\.\S+$)/ }
  ruby_strings = ruby_strings.reject { |s| s =~ /^[a-z_]+([ ,]+[a-z_]+)*$/ && s !~ / / }
  findings = words + ruby_strings.map { |s| "RB: #{s}" } + attrs.map { |a| "ATTR: #{a}" }.select { |a| a =~ /[A-Za-z]{3}/ && a !~ /^ATTR: <%/ }
  puts "#{f}: #{findings.uniq.inspect}" if findings.any?
end
