class AgoFormatter {
  constructor(locale) {
    this.relativeTimeFormatter = new Intl.RelativeTimeFormat(locale, { numeric: "always" })
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#ago(years, "year")
    if (months >= 1) return this.#ago(months, "month")
    if (weeks >= 1) return this.#ago(weeks, "week")
    if (days >= 1) return this.#ago(days, "day")
    if (hours >= 1) return this.#ago(hours, "hour")
    if (minutes >= 1) return this.#ago(minutes, "minute")

    return t("time.less_than_a_minute_ago")
  }

  #ago(quantity, unit) {
    return this.relativeTimeFormatter.format(-Math.floor(quantity), unit)
  }
}

// Formats a number of days relative to today ("today", "yesterday", "3 days ago", "in 3 days"),
// wrapping the styleable part in a span so it can be emphasized.
class RelativeDaysFormatter {
  constructor(locale) {
    this.relativeTimeFormatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })
  }

  formatDays(days) {
    const parts = this.relativeTimeFormatter.formatToParts(days, "day")

    if (parts.some(part => part.type === "integer")) {
      return parts.map(part => part.type === "integer" ? styleableValue(part.value) : part.value).join("")
    } else {
      return styleableValue(parts.map(part => part.value).join(""))
    }
  }
}

class DaysAgoFormatter extends RelativeDaysFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())
    return this.formatDays(-Math.max(days, 0))
  }
}

